# alerts/dashboard.py
from flask import Flask, render_template
import os

app = Flask(__name__)

# Trusted network device baseline configuration
trusted_devices = {
    "192.168.1.1": "AA:BB:CC:DD:EE:FF",  # Gateway / Router
    "192.168.1.15": "11:22:33:44:55:66" # Subnet Host / Victim VM
}

def get_live_alerts():
    """Reads alerts dynamically from the alerts.log file generated by notifier.py"""
    log_file = "alerts.log"
    if not os.path.exists(log_file):
        return []
    
    alerts = []
    with open(log_file, "r") as f:
        for line in f.readlines():
            if "WARNING" in line or "ALERT" in line:
                alerts.append(line.strip())
    return alerts[::-1]  # Show newest alerts first

@app.route('/')
def index():
    live_alerts = get_live_alerts()
    return render_template('index.html', devices=trusted_devices, alerts=live_alerts)

if __name__ == '__main__':
    app.run(debug=True, port=5000)